import React, { useState, useEffect } from 'react';
import styles from './CollapsibleSection.module.css';

interface CollapsibleSectionProps {
  /** DOM id — preserved for scrollToFirstErrorSection() compatibility */
  id?: string;
  /** Section heading; accepts ReactNode so callers can embed required marks */
  title: React.ReactNode;
  /** Field keys belonging to this section — drives the error badge */
  errorKeys?: string[];
  /** Full errors map from parent validation state */
  errors?: Record<string, string>;
  /** Default open/closed (default: true = expanded) */
  defaultExpanded?: boolean;
  children: React.ReactNode;
}

/**
 * CollapsibleSection
 *
 * Wraps a form card section with collapse / expand toggle.
 * When collapsed AND errorKeys has unresolved errors → shows a red "N lỗi" badge.
 * Auto-expands whenever a new error appears in its errorKeys (validation run).
 *
 * Usage:
 * ```tsx
 * <CollapsibleSection
 *   id="field-section-patient"
 *   title="Thông tin người bệnh"
 *   errorKeys={['patientName', 'departmentId']}
 *   errors={errors}
 * >
 *   <Input ... />
 * </CollapsibleSection>
 * ```
 */
export const CollapsibleSection: React.FC<CollapsibleSectionProps> = ({
  id,
  title,
  errorKeys = [],
  errors = {},
  defaultExpanded = true,
  children,
}) => {
  const [expanded, setExpanded] = useState(defaultExpanded);

  const errorCount = errorKeys.filter((k) => !!errors[k]).length;
  const hasErrors  = errorCount > 0;

  // Auto-expand when validation produces errors for fields in this section
  useEffect(() => {
    if (hasErrors) setExpanded(true);
  }, [hasErrors]);

  return (
    <section id={id} className={styles.section}>
      <button
        type="button"
        className={`${styles.header} ${hasErrors ? styles.headerError : ''}`}
        onClick={() => setExpanded((e) => !e)}
        aria-expanded={expanded}
      >
        <div className={styles.titleRow}>
          <h4 className={styles.title}>{title}</h4>
          {!expanded && hasErrors && (
            <span className={styles.errBadge}>
              <i className="fas fa-exclamation-circle" /> {errorCount} lỗi
            </span>
          )}
        </div>
        <i className={`fas fa-chevron-down ${styles.chevron} ${expanded ? styles.chevronOpen : ''}`} />
      </button>
      {expanded && <div className={styles.body}>{children}</div>}
    </section>
  );
};
