import React, { useMemo } from 'react';
import {
  SearchInput,
  createUserSearchConfig,
  type SearchInputConfig,
  type User,
} from '@linm-soft-org/linm-web-common-components';

interface IncidentUserSearchInputProps {
  value?: string;
  staffId?: string;
  fullName?: string;
  onChange: (userId: string, staffId: string, fullName: string) => void;
  label?: string;
  showLabel?: boolean;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
  error?: string;
}

/**
 * User lookup inside CollapsibleSection (`overflow: hidden`).
 * Portal + fixed column tracks so the panel anchors to the input
 * and the name column is not crushed to a few characters.
 */
/** API often leaves staffId empty and puts the employee code in username (L00041). */
function employeeCode(user: User): string {
  return (user.staffId || user.employeeId || user.username || '').trim();
}

function selectionMatchesTerm(user: User, term: string): boolean {
  const q = term.trim().toLowerCase();
  if (!q) return true;
  const haystack = [employeeCode(user), user.fullName, user.email, user.departmentName]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  return haystack.includes(q);
}

function useIncidentUserSearchConfig(selectedId?: string): SearchInputConfig<User> {
  return useMemo(() => {
    const base = createUserSearchConfig({ showDepartmentFilter: false });
    const search = base.api.search;
    const getDetail = base.api.getDetail;
    return {
      ...base,
      api: {
        ...base.api,
        search: async (args) => {
          const res = await search(args);
          const page = args.page ?? 1;
          if (!selectedId || !getDetail || page !== 1 || res.items.some((user) => user.id === selectedId)) {
            return res;
          }
          try {
            const current = await getDetail(selectedId);
            if (!current || !selectionMatchesTerm(current, args.search ?? '')) return res;
            return { ...res, items: [current, ...res.items] };
          } catch {
            return res;
          }
        },
      },
      display: {
        ...base.display,
        getPrimaryDisplay: (user) => user.fullName,
        getSingleDisplay: (user) => user.fullName,
      },
      dropdownPortal: true,
      dropdownMatch: 'container',
      dropdownMinWidth: '28rem',
      dropdownMaxWidth: 'min(720px, calc(100vw - 32px))',
      columns: (base.columns ?? []).map((col) => {
        if (col.key === 'staffId') {
          return {
            ...col,
            width: '6.5rem',
            align: 'start' as const,
            visible: (user: User) => !!employeeCode(user),
            render: (user: User) => employeeCode(user),
          };
        }
        if (col.key === 'fullName') return { ...col, width: 'minmax(10rem, 1fr)', align: 'start' as const };
        if (col.key === 'meta') return { ...col, width: 'minmax(9rem, 14rem)', align: 'start' as const };
        return col;
      }),
    };
  }, [selectedId]);
}

export const IncidentUserSearchInput: React.FC<IncidentUserSearchInputProps> = ({
  value,
  fullName,
  onChange,
  label,
  showLabel = false,
  placeholder,
  required,
  disabled,
  error,
}) => {
  const config = useIncidentUserSearchConfig(value);

  return (
    <SearchInput
      config={config}
      value={value}
      primaryDisplay={fullName || undefined}
      onChange={(user) => onChange(user.id, employeeCode(user), user.fullName)}
      onClear={() => onChange('', '', '')}
      label={showLabel ? label : undefined}
      showLabel={showLabel}
      placeholder={placeholder}
      showSecondaryInput={false}
      required={required}
      disabled={disabled}
      error={error}
    />
  );
};
