import React, { useMemo } from 'react';
import { CollapsibleSection } from './CollapsibleSection';
import {
  MedicalIncident,
} from '../../../models/MedicalIncident';
import { useFormOptions } from '../../../hooks/useFormOptions';
import {
  INCIDENT_NOTIFY_STATUS_OPTIONS,
  INCIDENT_OCCURRENCE_STATUS_OPTIONS,
  INCIDENT_REPORT_TYPE_OPTIONS,
  INCIDENT_SEVERITY_OPTIONS,
  withStaticFormOptionsFallback,
} from '../../../constants/incidentFormStaticOptions';
import { utcToLocalInputValue, localInputToISOWithOffset } from '../../../utils/dateTime';
import { IncidentUserSearchInput } from '../../../components/search/IncidentUserSearchInput';
import { IncidentLocationSearchInput } from '../../../components/search/IncidentLocationSearchInput';
import styles from './Tab1_IncidentInfo.module.css';
import {
  Input,
  TextArea,
  Select,
  RadioGroup,
  Checkbox,
} from '@linm-soft-org/linm-web-common-components';

interface Props {
  form: Partial<MedicalIncident>;
  onChange: (patch: Partial<MedicalIncident>) => void;
  isNew?: boolean;
  readOnly?: boolean;
  errors?: Record<string, string>;
}

// ─── Main component ───────────────────────────────────────────────────
export const Tab1IncidentInfo: React.FC<Props> = ({ form, onChange, isNew = false, readOnly, errors = {} }) => {
  const formName = isNew ? 'create-incident' : 'edit-incident';
  const {
    departmentOptions,
    patientGenderOptions,
    incidentSeverityOptions,
    incidentReportTypeOptions,
    incidentOccurrenceStatusOptions,
    incidentNotifyStatusOptions,
  } = useFormOptions(formName);

  const set = (key: keyof MedicalIncident) => (value: unknown) =>
    onChange({ [key]: value });

  const deptOptions = useMemo(
    () => [{ value: '', label: '(Tất cả khoa)' }, ...departmentOptions],
    [departmentOptions],
  );

  const allGenderOptions = useMemo(
    () => [{ value: '', label: 'Chọn...' }, ...patientGenderOptions],
    [patientGenderOptions],
  );

  const departments = departmentOptions.map((o) => ({ id: String(o.value), name: o.label }));

  /** Cast SelectOption[] (value: string|number) to RadioGroup-compatible { value: string; label: string }[] */
  const toRadioOpts = (opts: { value: string | number; label: string }[]) =>
    opts.map((o) => ({ value: String(o.value), label: o.label }));

  const reportTypeOptions = useMemo(
    () => toRadioOpts(withStaticFormOptionsFallback(incidentReportTypeOptions, INCIDENT_REPORT_TYPE_OPTIONS)),
    [incidentReportTypeOptions],
  );
  const notifyStatusOptions = useMemo(
    () => toRadioOpts(withStaticFormOptionsFallback(incidentNotifyStatusOptions, INCIDENT_NOTIFY_STATUS_OPTIONS)),
    [incidentNotifyStatusOptions],
  );
  const occurrenceStatusOptions = useMemo(
    () => toRadioOpts(withStaticFormOptionsFallback(incidentOccurrenceStatusOptions, INCIDENT_OCCURRENCE_STATUS_OPTIONS)),
    [incidentOccurrenceStatusOptions],
  );
  const severityOptions = useMemo(
    () => toRadioOpts(withStaticFormOptionsFallback(incidentSeverityOptions, INCIDENT_SEVERITY_OPTIONS)),
    [incidentSeverityOptions],
  );

  return (
    <div className={styles.container}>
      {/* ── LEFT COLUMN ──────────────────────────────────────────────────── */}
      <div className={styles.leftCol}>

        {/* Patient info */}
        <CollapsibleSection id="field-section-patient" title="Thông tin người bệnh" errorKeys={['patientName', 'departmentId']} errors={errors}>
          <div className={styles.row2}>
            <Input
              id="incident-patient-code"
              label="Mã bệnh nhân"
              value={form.patientCode ?? ''}
              onChange={(e) => set('patientCode')(e.target.value)}
              fullWidth
              readOnly={readOnly}
            />
            <Input
              id="incident-patient-name"
              label="Họ tên"
              value={form.patientName ?? ''}
              onChange={(e) => set('patientName')(e.target.value)}
              fullWidth
              readOnly={readOnly}
              error={errors.patientName}
            />
          </div>
          <div className={styles.row2}>
            <Input
              id="incident-patient-dob"
              label="Ngày sinh"
              type="date"
              value={form.patientDob ?? ''}
              onChange={(e) => set('patientDob')(e.target.value)}
              fullWidth
              readOnly={readOnly}
            />
            <Select
              id="incident-patient-gender"
              label="Giới tính"
              value={form.patientGender ?? ''}
              onChange={(e) => set('patientGender')(e.target.value)}
              options={allGenderOptions}
              fullWidth
              disabled={readOnly}
            />
            
          </div>
          <div className={styles.row2}>
            <Select
              id="incident-department-id"
              label="Khoa"
              value={form.departmentId ?? ''}
              onChange={(e) => {
                const dept = departments.find((d) => d.id === e.target.value);
                onChange({ departmentId: e.target.value, departmentName: dept?.name ?? '' });
              }}
              options={deptOptions}
              fullWidth
              disabled={readOnly}
              // required
              // error={errors.departmentId}
            />
            <Input
              id="incident-room-name"
              label="Phòng"
              value={form.roomName ?? ''}
              onChange={(e) => set('roomName')(e.target.value)}
              fullWidth
              readOnly={readOnly}
            />
          </div>
        </CollapsibleSection>

        {/* Report info */}
        <CollapsibleSection id="field-section-report" title="Thông tin báo cáo" errorKeys={['occurredAt']} errors={errors}>
          <RadioGroup
            id="incident-report-type"
            label="Hình thức báo cáo sự cố:"
            name="reportType"
            options={reportTypeOptions}
            value={form.reportType ?? (reportTypeOptions[0]?.value ?? '')}
            onChange={(v) => set('reportType')(v)}
            disabled={readOnly}
          />
          <div className={styles.row2}>
            <div className={styles.fieldCell}>
              <Input
                id="incident-created-at"
                label="Thời gian tạo"
                type="datetime-local"
                value={utcToLocalInputValue(form.createdAt)}
                onChange={(e) => set('createdAt')(localInputToISOWithOffset(e.target.value))}
                fullWidth
                readOnly
              />
            </div>
            <div className={styles.fieldCell}>
              <IncidentUserSearchInput
                label="Người tạo báo cáo"
                showLabel
                value={form.reportedById ?? ''}
                fullName={form.reportedByName ?? ''}
                onChange={(userId, _staffId, fullName) =>
                  onChange({ reportedById: userId || null, reportedByName: fullName })
                }
                placeholder="Tìm theo mã hoặc tên..."
                disabled={readOnly}
              />
            </div>
          </div>
          <div className={styles.row2}>
            <Input
              id="incident-occurred-at"
              label="Thời gian xảy ra"
              type="datetime-local"
              value={utcToLocalInputValue(form.occurredAt)}
              onChange={(e) => set('occurredAt')(localInputToISOWithOffset(e.target.value))}
              fullWidth
              readOnly={readOnly}
              required
              error={errors.occurredAt}
            />
            <Select
              id="incident-reporting-department-id"
              label="Khoa báo cáo"
              value={form.reportingDepartmentId ?? ''}
              onChange={(e) => {
                const dept = departments.find((d) => d.id === e.target.value);
                onChange({ reportingDepartmentId: e.target.value, reportingDepartmentName: dept?.name ?? '' });
              }}
              options={deptOptions}
              fullWidth
              disabled={readOnly}
            />
          </div>
          <div className={styles.row2}>
            <Input
              id="incident-id-code"
              label="Mã sự cố y khoa"
              value={form.idCode ?? ''}
              onChange={(e) => set('idCode')(e.target.value)}
              fullWidth
              readOnly
              placeholder="(Tự động tạo)"
            />
            <Input
              id="incident-name"
              label="Tên sự cố y khoa"
              value={form.incidentName ?? ''}
              onChange={(e) => set('incidentName')(e.target.value)}
              fullWidth
              readOnly={readOnly}
            />
          </div>
        </CollapsibleSection>

        {/* Incident subject */}
        <CollapsibleSection
          id="field-section-incident-subject"
          title={<>Đối tượng xảy ra sự cố{!readOnly && <span className={styles.requiredMark}> *</span>}</>}
          errorKeys={['subjectPatient']}
          errors={errors}
        >
          <div className={`${styles.checkGrid} ${errors.subjectPatient ? styles.radioGroupError : ''}`}>
            <Checkbox id="incident-subject-patient" label="Người bệnh"                     checked={form.subjectPatient   ?? false} onChange={(e) => set('subjectPatient')(e.target.checked)}   disabled={readOnly} />
            <Checkbox id="incident-subject-staff" label="Nhân viên y tế"                checked={form.subjectStaff     ?? false} onChange={(e) => set('subjectStaff')(e.target.checked)}     disabled={readOnly} />
            <Checkbox id="incident-subject-visitor" label="Người nhà/khách đến thăm"       checked={form.subjectVisitor   ?? false} onChange={(e) => set('subjectVisitor')(e.target.checked)}   disabled={readOnly} />
            <Checkbox id="incident-subject-equipment" label="Trang thiết bị/cơ sở hạ tầng" checked={form.subjectEquipment ?? false} onChange={(e) => set('subjectEquipment')(e.target.checked)} disabled={readOnly} />
          </div>
          {errors.subjectPatient && <span className={styles.radioError}>{errors.subjectPatient}</span>}
        </CollapsibleSection>

        {/* Locations */}
        <CollapsibleSection id="field-section-locations" title="Địa điểm xảy ra sự cố" errorKeys={['incidentDepartmentLocation', 'specificLocation']} errors={errors}>
          <div className={styles.locationFields}>
            <IncidentLocationSearchInput
              mode="department_room"
              label="Khoa/phòng/vị trí xảy ra sự cố"
              value={form.incidentDepartmentLocation ?? ''}
              onChange={(v) => set('incidentDepartmentLocation')(v)}
              required
              disabled={readOnly}
              error={errors.incidentDepartmentLocation}
            />
            <IncidentLocationSearchInput
              mode="specific_location"
              label="Vị trí cụ thể (ví dụ: nhà vệ sinh, bãi đậu xe...)"
              value={form.specificLocation ?? ''}
              onChange={(v) => set('specificLocation')(v)}
              required
              disabled={readOnly}
              error={errors.specificLocation}
            />
          </div>
        </CollapsibleSection>

        {/* Descriptions */}
        <CollapsibleSection id="field-section-description" title="Mô tả sự cố" errorKeys={['briefDescription', 'initialSolution', 'initialTreatment']} errors={errors}>
          <TextArea
            id="incident-brief-description"
            label="Mô tả ngắn gọn về sự cố"
            value={form.briefDescription ?? ''}
            onChange={(e) => set('briefDescription')(e.target.value)}
            rows={3}
            fullWidth
            readOnly={readOnly}
            required
            error={errors.briefDescription}
          />
          <TextArea
            id="incident-initial-solution"
            label="Đề xuất giải pháp ban đầu"
            value={form.initialSolution ?? ''}
            onChange={(e) => set('initialSolution')(e.target.value)}
            rows={3}
            fullWidth
            readOnly={readOnly}
            required
            error={errors.initialSolution}
          />
          <TextArea
            id="incident-initial-treatment"
            label="Điều trị/xử trí ban đầu đã được thực hiện"
            value={form.initialTreatment ?? ''}
            onChange={(e) => set('initialTreatment')(e.target.value)}
            rows={3}
            fullWidth
            readOnly={readOnly}
            required
            error={errors.initialTreatment}
          />
        </CollapsibleSection>
      </div>

      {/* ── RIGHT COLUMN ─────────────────────────────────────────────────── */}
      <div className={styles.rightCol}>

        {/* Notifications */}
        <CollapsibleSection id="field-section-notifications" title="Thông báo & Ghi nhận" errorKeys={['notifyDoctor', 'recordInMedicalRecord', 'notifyFamily', 'notifyPatient']} errors={errors}>
          <RadioGroup
            id="incident-notify-doctor"
            label="Thông báo cho Bác sĩ điều trị/người có trách nhiệm"
            name="notifyDoctor"
            options={notifyStatusOptions}
            value={form.notifyDoctor ?? ''}
            onChange={(v) => set('notifyDoctor')(v)}
            disabled={readOnly}
            required
            error={errors.notifyDoctor}
          />
          <RadioGroup
            id="incident-record-in-medical-record"
            label="Ghi nhận vào hồ sơ bệnh án/giấy tờ liên quan"
            name="recordInMedicalRecord"
            options={notifyStatusOptions}
            value={form.recordInMedicalRecord ?? ''}
            onChange={(v) => set('recordInMedicalRecord')(v)}
            disabled={readOnly}
            required
            error={errors.recordInMedicalRecord}
          />
          <RadioGroup
            id="incident-notify-family"
            label="Thông báo cho người nhà/người bảo hộ"
            name="notifyFamily"
            options={notifyStatusOptions}
            value={form.notifyFamily ?? ''}
            onChange={(v) => set('notifyFamily')(v)}
            disabled={readOnly}
            required
            error={errors.notifyFamily}
          />
          <RadioGroup
            id="incident-notify-patient"
            label="Thông báo cho người bệnh"
            name="notifyPatient"
            options={notifyStatusOptions}
            value={form.notifyPatient ?? ''}
            onChange={(v) => set('notifyPatient')(v)}
            disabled={readOnly}
            required
            error={errors.notifyPatient}
          />
        </CollapsibleSection>

        {/* Initial classification */}
        <CollapsibleSection id="field-section-classification" title="Phân loại ban đầu" errorKeys={['occurrenceStatus', 'severity']} errors={errors}>
          <RadioGroup
            id="incident-occurrence-status"
            label="Phân loại ban đầu về sự cố"
            name="occurrenceStatus"
            options={occurrenceStatusOptions}
            value={form.occurrenceStatus ?? ''}
            onChange={(v) => set('occurrenceStatus')(v)}
            disabled={readOnly}
            required
            error={errors.occurrenceStatus}
          />
          <RadioGroup
            id="incident-severity"
            label="Đánh giá ban đầu về mức độ ảnh hưởng của sự cố"
            name="severity"
            options={severityOptions}
            value={form.severity ?? ''}
            onChange={(v) => set('severity')(v)}
            disabled={readOnly}
            required
            error={errors.severity}
          />
        </CollapsibleSection>

        {/* Reporter info */}
        <CollapsibleSection id="field-section-reporter" title="Thông tin người thông báo" errorKeys={['reporterIsNurse']} errors={errors}>
          <Input
            id="incident-reporter-name"
            label="Họ tên:"
            value={form.reporterName ?? ''}
            onChange={(e) => set('reporterName')(e.target.value)}
            fullWidth
            readOnly={readOnly}
          />
          <Input
            id="incident-reporter-phone"
            label="Số điện thoại:"
            value={form.reporterPhone ?? ''}
            onChange={(e) => set('reporterPhone')(e.target.value)}
            fullWidth
            readOnly={readOnly}
          />
          <Input
            id="incident-reporter-email"
            label="Email:"
            type="email"
            value={form.reporterEmail ?? ''}
            onChange={(e) => set('reporterEmail')(e.target.value)}
            fullWidth
            readOnly={readOnly}
          />
          <div>
            <span className={styles.checkGroupLabel}>
              Chức danh người thông báo
              {!readOnly && <span className={styles.requiredMark}> *</span>}
            </span>
            <div className={`${styles.checkGrid2} ${errors.reporterIsNurse ? styles.radioGroupError : ''}`}>
              <Checkbox id="reporter-is-nurse" label="Điều dưỡng (chức danh)"   checked={form.reporterIsNurse   ?? false} onChange={(e) => set('reporterIsNurse')(e.target.checked)}   disabled={readOnly} />
              <Checkbox id="reporter-is-patient" label="Người bệnh"                checked={form.reporterIsPatient ?? false} onChange={(e) => set('reporterIsPatient')(e.target.checked)} disabled={readOnly} />
              <Checkbox id="reporter-is-visitor" label="Người nhà/khách đến thăm" checked={form.reporterIsVisitor ?? false} onChange={(e) => set('reporterIsVisitor')(e.target.checked)} disabled={readOnly} />
              <Checkbox id="reporter-is-doctor" label="Bác sĩ (chức danh)"       checked={form.reporterIsDoctor  ?? false} onChange={(e) => set('reporterIsDoctor')(e.target.checked)}  disabled={readOnly} />
            </div>
            {errors.reporterIsNurse && <span className={styles.radioError}>{errors.reporterIsNurse}</span>}
          </div>
          <div className={styles.checkWithInput}>
            <Checkbox id="reporter-is-other" label="Khác (ghi cụ thể)" checked={form.reporterIsOther ?? false} onChange={(e) => set('reporterIsOther')(e.target.checked)} disabled={readOnly} />
            {form.reporterIsOther && (
              <Input
                id="incident-reporter-other-detail"
                value={form.reporterOtherDetail ?? ''}
                onChange={(e) => set('reporterOtherDetail')(e.target.value)}
                fullWidth
                readOnly={readOnly}
              />
            )}
          </div>
          <Input
            id="incident-witness-1"
            label="Người chứng kiến 1"
            value={form.witness1 ?? ''}
            onChange={(e) => set('witness1')(e.target.value)}
            fullWidth
            readOnly={readOnly}
          />
          <Input
            id="incident-witness-2"
            label="Người chứng kiến 2"
            value={form.witness2 ?? ''}
            onChange={(e) => set('witness2')(e.target.value)}
            fullWidth
            readOnly={readOnly}
          />
        </CollapsibleSection>
      </div>
    </div>
  );
};
